INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29839$nota-0260$m29839$, $m29840$Exercise Physiology McArdle.pdf$m29840$, $m29841$631$m29841$, $m29842$The ACSM recommends that sports drinks contain 0.5 to 0.7 g of sodium per liter of fluid consumed during activity lasting more than 1 hr.$m29842$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29843$nota-0260$m29843$, $m29844$Exercise Physiology McArdle.pdf$m29844$, $m29845$631$m29845$, $m29846$With prolonged effort in the heat, sweat loss can deplete the body of 13 to 17 g of salt (2.3–3.4 g·L−1 of sweat) daily, about 8 g more than typically consumed. It seems prudent in this deficit situation to replace the lost sodium by adding about one-third teaspoon of table salt to 1 L of water.$m29846$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29847$nota-0260$m29847$, $m29848$nota-0227$m29848$, $m29849$complementa$m29849$, $m29850$nota-0227 cobre volume de fluido e carboidrato; esta nota cobre especificamente a reposição de sódio, terceiro componente da bebida de reposição em exercício prolongado no calor$m29850$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29851$nota-0260$m29851$, $m29852$nota-0259$m29852$, $m29853$complementa$m29853$, $m29854$protocolo ACSM de volume de fluido (nota-0259), citado no corpo da nota junto com nota-0227 como a recomendação que esta nota complementa com a dimensão de eletrólitos — link estrutural ausente até auditoria de 2026-08-02$m29854$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29855$nota-0260$m29855$, $m29856$nota-0261$m29856$, $m29857$complementa$m29857$, $m29858$cãibras por calor (nota-0261), citada no corpo da nota como o quadro clínico mais relevante para atletas com histórico — link estrutural ausente até auditoria de 2026-08-02$m29858$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29859$nota-0285$m29859$, $m29860$Exercise Physiology McArdle.pdf$m29860$, $m29861$809$m29861$, $m29862$A prudent dietary approach to weight loss unbalances the energy balance equation by reducing energy intake by 300 to 1000 kcal below daily energy expenditure. Moderately reduced energy intake (300 to 500 kcal daily) produces greater fat loss relative to the energy deficit than more severe energy restriction.$m29862$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29863$nota-0285$m29863$, $m29864$Exercise Physiology McArdle.pdf$m29864$, $m29865$809$m29865$, $m29866$Individuals who create larger daily deficits to lose weight more rapidly tend to regain weight compared to those who lose weight at a slower rate.$m29866$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29867$nota-0285$m29867$, $m29868$nota-0225$m29868$, $m29869$complementa$m29869$, $m29870$nota-0225 trata de déficit energético agudo em ultraendurance (contexto de prova); esta nota trata de déficit planejado para perda de peso ao longo de semanas/meses$m29870$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29871$nota-0286$m29871$, $m29872$Exercise Physiology McArdle.pdf$m29872$, $m29873$810$m29873$, $m29874$The 3500-kcal rule posits that 3500 kcal are 'used up' for each one pound of weight loss, a model advocated in this text, on respected government-and health-related web sites, and scientific research publications. Nonetheless, new research suggests that this rule grossly overestimates actual weight loss.$m29874$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29875$nota-0286$m29875$, $m29876$Exercise Physiology McArdle.pdf$m29876$, $m29877$810$m29877$, $m29878$The researchers have made downloadable applications... which simulate a rigorously validated, dynamic model of expected weight change... offer a convenient and potentially more accurate alternative to the 3500-kcal rule than incorporated in most smartphone apps and commercial weight-loss reducing regimens.$m29878$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29879$nota-0286$m29879$, $m29880$nota-0285$m29880$, $m29881$complementa$m29881$, $m29882$ambas tratam da relação entre déficit calórico e perda de peso real; esta nota qualifica a regra estática usada para estimar quanto peso um dado déficit produzirá$m29882$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29883$nota-0288$m29883$, $m29884$Exercise Physiology McArdle.pdf$m29884$, $m29885$823$m29885$, $m29886$Adding physical activity to a weight-loss program favorably modifies the composition of the weight lost in the direction of greater fat loss, less lean tissue loss, and the maintenance or even enhancement of physical capacity.$m29886$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29887$nota-0288$m29887$, $m29888$Exercise Physiology McArdle.pdf$m29888$, $m29889$823$m29889$, $m29890$Decreases in thigh muscle volume of 6.8% and composite knee flexion strength (27%), and VO2max (27%) occurred only in the caloric restriction group, whereas VO2max increased 15.5% in the group losing weight via exercise. Clearly, muscle mass, muscle strength, and aerobic capacity decreased in response to 12 mo of weight loss by caloric restriction, but not in response to similar exercise-induced weight loss.$m29890$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29891$nota-0288$m29891$, $m29892$nota-0285$m29892$, $m29893$complementa$m29893$, $m29894$nota-0285 trata da magnitude do déficit calórico; esta nota trata de como o déficit é criado (restrição alimentar vs. aumento de exercício) e seu efeito na composição da perda$m29894$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29895$nota-0291$m29895$, $m29896$Exercise Physiology McArdle.pdf$m29896$, $m29897$741$m29897$, $m29898$Amenorrhea occurs in 2 to 5% of women of reproductive age in the general population, but it can reach 40% in some athletic groups. As a group, ballet dancers remain lean, with a greater incidence of menstrual dysfunction and eating disorders... One third to one half of female endurance athletes exhibit some menstrual irregularity.$m29898$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29899$nota-0291$m29899$, $m29900$Exercise Physiology McArdle.pdf$m29900$, $m29901$742$m29901$, $m29902$Some researchers assert that 17% body fat represents a lower-end critical level for the onset of menstruation, with 22% fat needed to sustain a normal menstrual cycle... Objective data indicate that many physically active females who are below the supposedly critical 17% body fat level have normal menstrual cycles with high levels of physiologic and exercise capacity. Conversely, some amenorrheic athletes maintain body fat levels considered average for the population.$m29902$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m29903$nota-0291$m29903$, $m29904$Exercise Physiology McArdle.pdf$m29904$, $m29905$742$m29905$, $m29906$A prolonged level of physical stress may disrupt the hypothalamic-pituitary-adrenal axis... (exercise stress hypothesis). A concurrent hypothesis maintains that energy (fat) reserves inadequate to sustain pregnancy induce cessation of ovulation (energy availability hypothesis).$m29906$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29907$nota-0291$m29907$, $m29908$nota-0225$m29908$, $m29909$complementa$m29909$, $m29910$nota-0225 trata de déficit energético agudo em ultraendurance; esta nota trata da consequência hormonal crônica de déficit energético sustentado em atletas mulheres$m29910$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m29911$nota-0291$m29911$, $m29912$nota-0237$m29912$, $m29913$complementa$m29913$, $m29914$nota-0237 trata de osteoporose e cálcio em ciclistas; amenorreia prolongada agrava perda óssea, tema relacionado$m29914$)
